// Widen any verilator signal type to uint64_t.
// Scalars (bool/u8/u32/u64) widen via static_cast.
// VlWide<N> (m_storage array): take low 64 bits.
template<typename T>
uint64_t widen_to_u64(const T& v)
{
  if constexpr (std::is_convertible_v<T, uint64_t>)
    return static_cast<uint64_t>(v);
  else // VlWide<N>
    return (static_cast<uint64_t>(v.m_storage[1]) << 32)
         | static_cast<uint64_t>(v.m_storage[0]);
}

template<typename Derived>
class CpuSignalRegistry
{
public:
  // Stateless lambdas decay to function pointers — no std::function overhead.
  using SignalAccessor = uint64_t (*)(const Derived&);
  using Registry = std::unordered_map<std::string, SignalAccessor>;

  uint64_t get_signal(const std::string& name) const
  {
    auto it = registry().find(name);
    if (it == registry().end())
      throw std::runtime_error("Unknown signal: " + name);
    return it->second(static_cast<const Derived&>(*this));
  }

  bool has_signal(const std::string& name) const
  {
    return registry().contains(name);
  }

  std::vector<std::string> list_signals() const
  {
    std::vector<std::string> out;
    out.reserve(registry().size());
    for (auto& [k, _]: registry())
      out.push_back(k);
    return out;
  }

